#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int t=0; t<n-2; t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;

        // Move element from pos to position t using at most 2 operations
        // Step 1: Move element to position n-1
        if(pos != n-1){
            // x = pos+1, y = n-1-pos => x+y = n, too big
            // We need suffix of y to grab nothing past pos, and prefix of x to include pos
            // Use: x = pos+1, y = n-2-pos (if valid), element goes to position n-2-pos (middle start... no)
            // After op(x,y): new[0..y-1] = old[n-y..n-1], new[y..n-x-1] = old[x..n-y-1], new[n-x..n-1] = old[0..x-1]
            // Element at old[pos] with x=pos+1: it's old[pos] = old[x-1], goes to new[n-x+x-1-0] = new[n-1]
            // So x=pos+1, and we need y>=1, x+y<n => y can be 1..n-pos-2
            // pos+1+1 < n => pos < n-2, which is true since pos < n and pos != n-1
            if(pos+1 > 0 && pos+1+1 < n){
                apply_op(pos+1, 1);
                // Element was at old[pos]=old[x-1], now at new[n-1]
            }
        }
        // Now element should be at position n-1
        // Step 2: Move from n-1 to t
        // Use y=1: suffix grabs p[n-1], puts it at new[0]. Then prefix of x goes to end.
        // new[0]=target, new[1..n-x-1]=old[x..n-2], new[n-x..n-1]=old[0..x-1]
        // We want target at position t. With y=1: target at 0, then use x=n-1-t (if valid)
        // Actually: use x=1,y=t+1 if t+1>=1: new = old[n-t-1..n-1]+old[1..n-t-2]+old[0]
        // target=old[n-1] at new[t]. 
        if(t > 0 && 1+t < n){
            apply_op(1, t);
            // old[n-1] goes to new[t-1]... let me just use y=t+1 if valid
        } else {
            // t==0: x=1,y=1 => target at 0? 
            if(1+1<n) apply_op(1,1);
        }
        // Verify and fix with brute force if needed
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
